def transform(grid):
    wall_color = 5
    fill_color = 8
    output = []

    for r in range(0, len(grid), 4):
        row_vals = []
        for c in [0, 8, 16, 24]:
            if c < len(grid[0]):
                val = grid[r][c]
                if val == wall_color:
                    row_vals.append(fill_color)
                else:
                    row_vals.append(val)

        # Apply rule: for consecutive duplicate markers, first becomes fill
        processed_row = []
        for i in range(len(row_vals)):
            if i > 0 and row_vals[i] == row_vals[i-1]:
                processed_row.append(fill_color)
            else:
                processed_row.append(row_vals[i])
        output.append(processed_row)

    return output
